  bindCredits(); document.querySelectorAll('[data-top]').forEach((b) => (b.onclick = () => { SKILL_TOP = b.dataset.top; pageSkills(); })); document.querySelectorAll('[data-c]').forEach((b) => (b.onclick = () => { SKILL_TAB = b.dataset.c; pageSkills(); }));
